    // ── Hiệu ứng tương tác (chuyển từ CSS sang JS) ──
    function addInteractiveEffect(elements, hoverStyles, defaultStyles, activeStyles) {
        var els = (elements instanceof NodeList || Array.isArray(elements)) ? elements : [elements];
        els.forEach(function (el) {
            if (!el) return;

            el.addEventListener('mouseenter', function () {
                Object.assign(el.style, hoverStyles);
            });
            el.addEventListener('mouseleave', function () {
                Object.assign(el.style, defaultStyles);
            });
            if (activeStyles) {
                el.addEventListener('mousedown', function () {
                    Object.assign(el.style, activeStyles);
                });
                el.addEventListener('mouseup', function () {
                    Object.assign(el.style, hoverStyles);
                });
            }
        });
    }

