                    var t44 = document.getElementById('PhIXanh');
                    [t48, t49, t44].forEach(function (t) {
                        if (t) { t.style.display = 'block'; t.style.opacity = '0'; setTimeout(function () { t.style.opacity = '1'; }, 10); }
                    });

                    // Reset Heart
                    var t8 = document.getElementById('Tim');
